-- deploy28g wording fixes on -2 pages only (spelling/grammar/punctuation). Idempotent: each REPLACE runs only where the old text is present and the new text is not.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_520_ci;
UPDATE wp_postmeta m JOIN wp_posts p ON p.ID=m.post_id SET m.meta_value=REPLACE(m.meta_value,'They are the body''s most precise signalling molecules.','It is the body''s most precise signalling molecules.') WHERE m.meta_key='_elementor_data' AND p.post_type='page' AND p.post_name='what-are-peptides-2' AND LOCATE('They are the body''s most precise signalling molecules.',m.meta_value)>0 AND LOCATE('It is the body''s most precise signalling molecules.',m.meta_value)=0;
